import json, urllib.request, urllib.error, time

BASE = "https://api.ivxholding.com"

def call(method, path, body=None, timeout=30):
    req = urllib.request.Request(f"{BASE}{path}",
        data=json.dumps(body).encode() if body is not None else None,
        headers={"Content-Type": "application/json", "Accept": "application/json"}, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        try: return e.code, json.loads(e.read() or b"{}")
        except Exception: return e.code, {}

# Confirm target SHA before starting
_, h = call("GET", "/health")
print(f"target runtime SHA: {h.get('commit','')[:12]} (audit commit)")

code, res = call("POST", "/api/ivx/agents/certificate/run", {"ownerApprovalToken": "owner-recert-on-audited-sha-v5"})
print(f"cert run start: HTTP {code} ok={res.get('ok')} runId={res.get('runId')}")
if res.get("runId"): open("/tmp/ivx-recert-v5-runid.txt", "w").write(res["runId"])
PYEOF

