import json, urllib.request, time

def get(path):
    req = urllib.request.Request(f"https://api.ivxholding.com{path}", headers={"Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read() or b"{}")

for i in range(12):
    p = get("/api/ivx/agents/certificate/progress").get("activeRun") or {}
    print(f"poll {i}: {p.get('status')} phase={p.get('phase')} {p.get('processed')}/{p.get('total')} failed={p.get('failed')}")
    if p.get("status") in ("completed", "failed"):
        break
    time.sleep(8)
PYEOF

